<script setup>
import {computed,ref} from 'vue';
import ClinicalDiagnosisSearch from './ClinicalDiagnosisSearch.vue';
const props=defineProps({kind:{type:String,default:'diagnosis'},agencyId:[Number,String],sourceText:String,diagnosisMode:String,dateOfService:String,transport:Object,search:Function});
async function client(){return props.transport || (await import('../../services/api.js')).default;}
const emit=defineEmits(['apply']);
const open=ref(false),source=ref(''),result=ref(''),busy=ref(false),error=ref(''),confirmed=ref(false),selected=ref(null),query=ref(''),code=ref('');
const isService=computed(()=>props.kind==='service');
function begin(){source.value=props.sourceText || '';open.value=true;confirmed.value=false;error.value='';}
async function suggest(){busy.value=true;error.value='';try{const fd=new FormData();fd.append('agencyId',String(props.agencyId));fd.append('toolId',isService.value?'clinical_code_decider':'clinical_diagnosis_writer');fd.append('inputText',source.value+(props.diagnosisMode==='zr_only'?'\nSuggest only supported social-determinant Z codes. Do not establish a mental health disorder.':''));const {data}=await (await client()).post(props.transport?'/generate':'/clinical-notes/generate',props.transport?Object.fromEntries(fd):fd,{skipGlobalLoading:true});const sections=data.outputJson?.sections || {};result.value=Object.entries(sections).map(([title,text])=>title+'\n'+text).join('\n\n');if(!result.value)throw new Error('No suggestion returned.');confirmed.value=false;}catch(e){error.value=e.response?.data?.error?.message || e.message || 'The suggestion could not be completed.';}finally{busy.value=false;}}
function apply(){if(!confirmed.value)return;if(isService.value){if(!/^(?:\d{5}|H\d{4})$/.test(code.value.trim().toUpperCase())){error.value='Enter the recommended service code to verify.';return;}emit('apply',{serviceCode:code.value.trim().toUpperCase(),serviceReason:result.value});}else{if(!selected.value)return;emit('apply',{diagnosis:{...selected.value,justification:result.value,source:'Provider-reviewed diagnosis writer'}});}open.value=false;}
const allowed=row=>props.diagnosisMode!=='zr_only' || /^[ZR]/i.test(row.icd10_code || row.code || '');
</script>
<template><button type="button" class="assist-launch" @click="begin">{{isService?'Help choose a service':'Diagnosis writer & justification'}}</button><Teleport to="body"><div v-if="open" class="assist-backdrop"><section class="assist-dialog" role="dialog" aria-modal="true" :aria-label="isService?'Service code guidance':'Diagnosis guidance'"><header><h2>{{isService?'Review the service performed':'Review diagnoses and justification'}}</h2><button type="button" @click="open=false">Close</button></header><p>Use clinical content and roles. Confirm the recommendation before applying it. Service changes require encounter eligibility verification and confirmation.</p><label>Clinical information<textarea v-model="source" rows="5" /></label><button type="button" :disabled="busy || !source.trim()" @click="suggest">{{busy?'Preparing recommendation…':'Request recommendation'}}</button><p v-if="error" role="alert">{{error}}</p><template v-if="result"><label>Recommendation and rationale<textarea v-model="result" rows="9" @input="confirmed=false" /></label><label v-if="isService">Service code to verify<input v-model="code" maxlength="5" @input="confirmed=false" /></label><ClinicalDiagnosisSearch v-else v-model="query" label="Select the diagnosis you confirm" :agency-id="agencyId" :date-of-service="dateOfService" :filter-results="allowed" :search="search" @select="selected=$event;confirmed=false" /><p v-if="selected && !isService">{{selected.icd10_code || selected.code}} · {{selected.description}}</p><label class="assist-attest"><input v-model="confirmed" type="checkbox" /> I reviewed the evidence and recommendation, confirm it is within my clinical authority, and attest that it reflects this encounter.</label><button type="button" :disabled="!confirmed || !isService && !selected" @click="apply">{{isService?'Verify this service change':'Apply confirmed diagnosis and rationale'}}</button></template></section></div></Teleport></template>
<style scoped>.assist-launch{font:inherit!important;font-size:12px!important;min-height:34px;padding:6px 10px!important;border:1px solid #bcd0de!important;border-radius:7px;background:#f3f8fc;color:#285978}.assist-backdrop{position:fixed;inset:0;z-index:10020;background:#142d4560;display:grid;place-items:center;padding:20px}.assist-dialog{box-sizing:border-box;max-height:90dvh;overflow:auto;width:min(720px,100%);border-radius:14px;background:#fff;padding:22px;color:#203e54;font-size:14px}.assist-dialog header{display:flex;justify-content:space-between;gap:20px}.assist-dialog h2{font-size:18px;margin:0}.assist-dialog p{font-size:13px;line-height:1.6}.assist-dialog label{display:block;font-size:13px;margin:14px 0}.assist-dialog textarea,.assist-dialog input:not([type=checkbox]){box-sizing:border-box;display:block;width:100%;font:inherit;line-height:1.6;border:1px solid #bdcfdd;border-radius:7px;padding:10px;margin-top:6px}.assist-dialog button{font:inherit;font-size:13px;padding:9px 12px;border:1px solid #bbd0df;border-radius:7px;color:#174f76;background:#f2f7fc}.assist-dialog .assist-attest{display:flex;align-items:flex-start;gap:8px;line-height:1.6}</style>
